<?php
namespace App\Services; use App\Models\{EmployeeTrainingCredential,TrainingEvaluationAttempt,TrainingSession}; use Barryvdh\DomPDF\Facade\Pdf; use Illuminate\Support\Facades\{DB,Storage}; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class TrainingCertificateService{public function generate(TrainingSession$s,int$employee,string$type,int$user):EmployeeTrainingCredential{return DB::transaction(function()use($s,$employee,$type,$user){$participant=$s->attendanceEvent?->participants()->where('employee_id',$employee)->whereHas('record',fn($q)=>$q->where('status','confirmed'))->first();if(!$participant)throw ValidationException::withMessages(['certificate'=>'Se requiere asistencia confirmada.']);$attempt=null;if($type==='internal_approval_certificate'){$attempt=TrainingEvaluationAttempt::where('employee_id',$employee)->where('result','passed')->whereHas('evaluation',fn($q)=>$q->where('training_session_id',$s->id))->latest()->first();if(!$attempt)throw ValidationException::withMessages(['certificate'=>'Se requiere una evaluación aprobada.']);}$code=Str::random(48);$credential=EmployeeTrainingCredential::firstOrCreate(['training_session_id'=>$s->id,'employee_id'=>$employee,'credential_type'=>$type],['company_id'=>$s->company_id,'training_topic_id'=>$s->training_topic_id,'evaluation_attempt_id'=>$attempt?->id,'name'=>$type==='attendance_certificate'?'Constancia interna de participación':'Constancia interna de aprobación de capacitación','issuing_organization'=>$s->company->razon_social,'issued_at'=>now()->toDateString(),'verification_code'=>hash('sha256',$code),'status'=>'valid','created_by'=>$user]);if(!$credential->document_path){$credential->load('employee');$content=Pdf::loadView('pdf.training_certificate',compact('credential','s','code'))->output();$path="training/credentials/{$credential->id}.pdf";Storage::disk(config('training.evidence_disk','local'))->put($path,$content);$credential->update(['document_path'=>$path]);}return$credential;});}}
